draw:
var th = p.angle * Math.PI / 180;
var E = p.field, A = p.area;
var flux = E * A * Math.cos(th);
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";

// uniform field: drifting arrowheads on horizontal lines
ctx.strokeStyle = C.faint;
ctx.fillStyle = C.faint;
ctx.lineWidth = 1;
var rows = 7;
for (var i = 0; i < rows; i++) {
  var y = H * (i + 1) / (rows + 1);
  ctx.beginPath(); ctx.moveTo(W * 0.06, y); ctx.lineTo(W * 0.94, y); ctx.stroke();
  for (var j = 0; j < 4; j++) {
    var span = W * 0.88;
    var x = W * 0.06 + ((j * span / 4 + t * 26) % span);
    ctx.beginPath();
    ctx.moveTo(x, y); ctx.lineTo(x - 7, y - 3.5); ctx.lineTo(x - 7, y + 3.5);
    ctx.closePath(); ctx.fill();
  }
}

var cx = W * 0.46, cy = H * 0.5;
var L = Math.min(H * 0.33, W * 0.2);

// panel: normal at angle th from the field (+x); panel runs perpendicular to it
var nx = Math.cos(th), ny = Math.sin(th);
var dx = -Math.sin(th), dy = Math.cos(th);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 4;
ctx.beginPath();
ctx.moveTo(cx + dx * L, cy - dy * L);
ctx.lineTo(cx - dx * L, cy + dy * L);
ctx.stroke();

// normal arrow
var NL = L * 0.85;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(cx + nx * NL, cy - ny * NL);
ctx.stroke();
ctx.fillStyle = C.figure;
var ax = cx + nx * NL, ay = cy - ny * NL;
ctx.beginPath();
ctx.moveTo(ax, ay);
ctx.lineTo(ax - nx * 9 - ny * 5, ay + ny * 9 - nx * 5);
ctx.lineTo(ax - nx * 9 + ny * 5, ay + ny * 9 + nx * 5);
ctx.closePath(); ctx.fill();
ctx.fillText("normal", ax + 6, ay - 4);

// reference line along the field, and the angle
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + NL + 20, cy); ctx.stroke();
ctx.setLineDash([]);
ctx.beginPath();
ctx.arc(cx, cy, 26, -th, 0);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("angle " + p.angle.toFixed(0) + " deg", cx + 30, cy - 10 - 14 * Math.sin(th));
ctx.fillStyle = C.accent;
ctx.fillText("panel", cx + dx * L - 34, cy - dy * L - 6);
ctx.fillStyle = C.ink;
ctx.fillText("E = " + E.toFixed(0) + " N/C", W * 0.06, H - 6);

out.note = "flux = E A cos(angle) = " + E.toFixed(0) + " x " + A.toFixed(2) + " x " +
  Math.cos(th).toFixed(3) + " = " + flux.toFixed(1) + " N.m^2/C";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
var cy = H * 0.46;
var s = Math.min(W / 3, H) ;
var r = Math.min(s * 0.21, H * 0.26);

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var ux = x1 - x0, uy = y1 - y0, m = Math.sqrt(ux * ux + uy * uy);
  ux /= m; uy /= m;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - ux * 8 - uy * 4, y1 - uy * 8 + ux * 4);
  ctx.lineTo(x1 - ux * 8 + uy * 4, y1 - uy * 8 - ux * 4);
  ctx.closePath(); ctx.fill();
}

// ---- 1. sphere
var c1 = W / 6;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(c1, cy, r * 0.42, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.setLineDash([5, 4]);
ctx.beginPath(); ctx.arc(c1, cy, r, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);
for (var i = 0; i < 8; i++) {
  var a = i * Math.PI / 4;
  arrow(c1 + Math.cos(a) * r, cy + Math.sin(a) * r,
        c1 + Math.cos(a) * (r + 14), cy + Math.sin(a) * (r + 14), C.rule);
}
ctx.fillStyle = C.ink;
ctx.fillText("sphere, area 4 pi r^2", c1, H - 20);
ctx.fillText("E out everywhere", c1, H - 6);

// ---- 2. coaxial cylinder
var c2 = W / 2;
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(c2, cy - r * 1.25); ctx.lineTo(c2, cy + r * 1.25); ctx.stroke();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.setLineDash([5, 4]);
var cw = r * 0.85, ch = r * 0.75;
ctx.strokeRect(c2 - cw, cy - ch, cw * 2, ch * 2);
ctx.beginPath(); ctx.ellipse(c2, cy - ch, cw, cw * 0.28, 0, 0, Math.PI * 2); ctx.stroke();
ctx.beginPath(); ctx.ellipse(c2, cy + ch, cw, cw * 0.28, 0, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);
arrow(c2 + cw, cy, c2 + cw + 16, cy, C.rule);
arrow(c2 - cw, cy, c2 - cw - 16, cy, C.rule);
ctx.fillStyle = C.ink;
ctx.fillText("can, side area 2 pi r L", c2, H - 20);
ctx.fillText("flat ends catch nothing", c2, H - 6);

// ---- 3. pillbox in a sheet
var c3 = 5 * W / 6;
ctx.strokeStyle = C.figure; ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(c3 - r * 1.25, cy); ctx.lineTo(c3 + r * 1.25, cy); ctx.stroke();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.setLineDash([5, 4]);
var pw = r * 0.55, ph = r * 0.6;
ctx.strokeRect(c3 - pw, cy - ph, pw * 2, ph * 2);
ctx.setLineDash([]);
arrow(c3, cy - ph, c3, cy - ph - 16, C.rule);
arrow(c3, cy + ph, c3, cy + ph + 16, C.rule);
ctx.fillStyle = C.ink;
ctx.fillText("pillbox, two faces of area A", c3, H - 20);
ctx.fillText("curved side catches nothing", c3, H - 6);

ctx.textAlign = "left";

var k = 8.99e9;
var R = p.R / 100.0;
var Q = p.Q * 1e-9;
var rp = p.r / 100.0;
var rmax = 0.25;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

function Efield(r) {
  if (r <= 0) return 0;
  if (r < R) return k * Q * r / (R * R * R);
  return k * Q / (r * r);
}
var Epeak = k * Q / (R * R);
var Enow = Efield(rp);
var Qenc = rp < R ? Q * Math.pow(rp / R, 3) : Q;

// ---- left panel: cross section
var cx = W * 0.2, cy = H * 0.5;
var scale = Math.min(W * 0.17, H * 0.42) / rmax;
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.35;
ctx.beginPath(); ctx.arc(cx, cy, R * scale, 0, Math.PI * 2); ctx.fill();
ctx.globalAlpha = 1;
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(cx, cy, R * scale, 0, Math.PI * 2); ctx.stroke();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.setLineDash([5, 4]);
ctx.beginPath(); ctx.arc(cx, cy, rp * scale, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("Gaussian sphere", cx, H - 6);
ctx.textAlign = "left";

// ---- right panel: E versus r
var x0 = W * 0.42, x1 = W - 16, y0 = H - 30, y1 = 18;
var gw = x1 - x0, gh = y0 - y1;
var Emax = Math.max(Epeak * 1.15, 1);
var GX = function (r) { return x0 + r / rmax * gw; };
var GY = function (e) { return y0 - Math.min(e, Emax) / Emax * gh; };

ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, y1); ctx.lineTo(x0, y0); ctx.lineTo(x1, y0); ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(GX(R), y0); ctx.lineTo(GX(R), y1); ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 220; i++) {
  var r = rmax * i / 220;
  var X = GX(r), Y = GY(Efield(r));
  i === 0 ? ctx.moveTo(X, Y) : ctx.lineTo(X, Y);
}
ctx.stroke();

ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(GX(rp), GY(Enow), 4.5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("E (N/C)", x0 + 4, y1 + 4);
ctx.fillText("r (cm)", x1 - 36, y0 + 16);
ctx.fillText("0", x0 - 4, y0 + 16);
ctx.fillText("r = R", GX(R) + 4, y1 + 16);
ctx.fillText("25", x1 - 10, y0 + 16);

out.note = "r = " + p.r.toFixed(1) + " cm, enclosed charge " + (Qenc * 1e9).toFixed(2) +
  " nC, E = " + Enow.toFixed(0) + " N/C (surface value " + Epeak.toFixed(0) + " N/C)";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
var cx = W * 0.5, cy = H * 0.5;
var u = Math.min(W * 0.42, H * 0.44);
var rIn = u * 0.42, rOut = u * 0.68;

// metal shell
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.3;
ctx.beginPath();
ctx.arc(cx, cy, rOut, 0, Math.PI * 2);
ctx.arc(cx, cy, rIn, 0, Math.PI * 2, true);
ctx.fill();
ctx.globalAlpha = 1;
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(cx, cy, rOut, 0, Math.PI * 2); ctx.stroke();
ctx.beginPath(); ctx.arc(cx, cy, rIn, 0, Math.PI * 2); ctx.stroke();

// the charge in the cavity, off centre
var qx = cx - rIn * 0.45, qy = cy + rIn * 0.25;
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(qx, qy, 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText("+", qx, qy + 4);

// induced signs
ctx.fillStyle = C.ink;
for (var i = 0; i < 12; i++) {
  var a = i * Math.PI / 6;
  ctx.fillText("-", cx + Math.cos(a) * (rIn + 9), cy + Math.sin(a) * (rIn + 9) + 4);
  ctx.fillText("+", cx + Math.cos(a) * (rOut - 9), cy + Math.sin(a) * (rOut - 9) + 4);
}

// gaussian surface drawn inside the metal
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.setLineDash([5, 4]);
ctx.beginPath(); ctx.arc(cx, cy, (rIn + rOut) / 2, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);

// outside field arrows
ctx.strokeStyle = C.rule; ctx.fillStyle = C.rule; ctx.lineWidth = 1.5;
for (var j = 0; j < 8; j++) {
  var b = j * Math.PI / 4 + 0.39;
  var sx = cx + Math.cos(b) * (rOut + 4), sy = cy + Math.sin(b) * (rOut + 4);
  var ex = cx + Math.cos(b) * (rOut + 20), ey = cy + Math.sin(b) * (rOut + 20);
  ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(ex, ey); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(ex, ey);
  ctx.lineTo(ex - Math.cos(b) * 7 - Math.sin(b) * 3.5, ey - Math.sin(b) * 7 + Math.cos(b) * 3.5);
  ctx.lineTo(ex - Math.cos(b) * 7 + Math.sin(b) * 3.5, ey - Math.sin(b) * 7 - Math.cos(b) * 3.5);
  ctx.closePath(); ctx.fill();
}

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("E = 0 inside the metal", 8, 16);
ctx.fillText("inner wall: -q", 8, H - 20);
ctx.fillText("outer wall: +q, spread evenly", 8, H - 6);
ctx.textAlign = "center";
ctx.fillStyle = C.accent;
ctx.fillText("Gaussian surface encloses zero net charge", cx, cy - rOut - 6);
ctx.textAlign = "left";
